"""Draft watch293 data reader; cannot authorize anything without a primary receipt."""
import base64,json,tarfile
from pathlib import Path
from primary_controller_evidence import CHECKS,artifact_inventory,canonical,deny_noncore,file_sha,pinned,require,safe_member,sha,tar_members,unit_proof
FORMAT='primary-qualified-watch293-v1'
PRIMARY_RECEIPT_SHA256='d261cbaac376daaa67686d7939b85c0782d8f0d38fb8d823e598098f71261794'
FREEZE='3ea406c3e7df04057215b5ea221d8a565475afd1af60fe94850d855d94ff4641'
CORES={'static':'2511208dea53bf380088ca242ea5b26029ebfeceb1794d87fc42fde4df8f22ab','dynamic':'6f0e188ae4509e660fe472ae9d7ba368846c0161184556d5d925d5c527b8e0e2'}
CASE='migration-terminal213-watch-winch'; CONTROL='migration-terminal213-control-winch'
CASE_HASH='90d8f54e6546385232f1f260c017de6ccd949c1f3c2935877c78516b3e9597ec';CONTROL_HASH='8ab3f3d794830ef56a6ea10216fdd5a02a24e6dbfb4c79b65dfbe12c97b82a04'

def load_qualified_watch_run(spec,expected_binary,expected_build):
 require(PRIMARY_RECEIPT_SHA256 is not None,'watch primary acceptance receipt not pinned')
 deny_noncore(spec,'watch selection');require(spec.get('evidence_format')==FORMAT and expected_build in CORES and expected_binary==CORES[expected_build] and spec.get('ledger_scope')=='core' and spec.get('core_ledger_eligible') is True,'watch selection differs')
 rp=spec['primary_receipt'];require(rp['sha256']==PRIMARY_RECEIPT_SHA256,'watch receipt differs');receipt=json.loads(pinned(rp['path'],PRIMARY_RECEIPT_SHA256,'watch primary receipt'))
 # The receipt is an explicit source authority, not a substitute for input checks.
 require(receipt.get('schema')=='bashos-watch-winch-primary-acceptance-20261029-v1' and receipt.get('decision')=='accept-both-reached-watch-resize-FAIL-observations' and receipt.get('source_freeze_sha256')==FREEZE and receipt.get('ledger_scope')=='core' and receipt.get('core_ledger_eligible') is True and receipt.get('requirement')=={'topic':'watch/watch-terminal-parity','id':'r6','behavior':'Resize redraw (SIGWINCH) re-renders at the new width.'},'watch receipt scope differs')
 a=receipt['runs'][expected_build];require(spec.get('groups')==['terminal'] and spec.get('ids')==[CASE] and a['candidate_sha256']==expected_binary and a['case_sha256']==CASE_HASH and a['status']=='FAIL' and a['candidate']==expected_build and a['case_id']==CASE and a['control_case_sha256']==CONTROL_HASH and a['artifact_inventory_verified'] is True and a['payload_source_files_verified']==12 and spec.get('name')=='watch293-'+expected_build and not spec.get('exclude_ids'),'watch receipt run differs');root=Path(spec['path']);require(root.is_absolute() and str(root.resolve(strict=True))==a['source_result'],'watch result path differs');core=Path(spec['core_binary_path']);require(core.is_absolute() and file_sha(core)==expected_binary,'watch core differs')
 fs=spec['source_freeze'];require(fs['sha256']==FREEZE,'watch freeze pin differs');fp=Path(fs['path']);f=json.loads(pinned(fp,FREEZE,'watch freeze'));require(f['schema']=='bashos-terminal293-primary-source-freeze-v1','watch freeze differs');inventory=json.loads(pinned(fp.parent/'control-files.json',f['inventories']['control-files.json'],'watch source inventory'))
 p=json.loads(pinned(root/'provenance.json',a['provenance_sha256'],'watch provenance'));u=a['vm_uuid'];require(p['operation']=='terminal213-run' and p['status']=='completed' and p['batch']=='watch-winch' and p['candidate']==expected_build and p['candidate_sha256']==expected_binary and p['vm_uuid']==u and p['selected_case_ids']==[CONTROL,CASE] and p['canonical_case_sha256']=={CONTROL:CONTROL_HASH,CASE:CASE_HASH} and p['root_fixtures_allowed'] is False and p['host_mounts']==[] and p['identity']['marker_matches'] and p['identity']['product_uuid_matches'] and not p['identity']['host_shared_mounts'] and p['runtime_network']['canary_accepted']==0,'watch provenance differs')
 require(p['workspace_core_before']==p['workspace_core_after'] and p['workspace_core_before'].get(str(core))==expected_binary and p['core_before']==p['core_after'] and p['prepared_sha256']==a['prepared_sha256'] and p['image_identity']['sha256']==a['image_identity_sha256_field'] and p['guest_summary_sha256']==a['summary_sha256'] and p['prepared_sha256']==f['pins']['prepared_image_sha256'],'watch core or image identity fields differ')
 require(all(p.get(k) is True for k in ('candidate_unchanged','candidate_snapshot_unchanged','prepared_unchanged','controller_unchanged','module_unchanged','suites_unchanged','helpers_unchanged','guest_units_proven_quiescent','scope_proven','overlay_discarded','evidence_unchanged')),'watch integrity or lifecycle differs');artifact_inventory(root,p);require(not (root/'overlay.qcow2').exists() and file_sha(root/'candidate.snapshot')==expected_binary and file_sha(root/'payload.tar')==a['payload_sha256']==p['payload_sha256'] and file_sha(root/'evidence.tar')==a['evidence_sha256']==p['evidence_validation']['archive_sha256'],'watch evidence archive differs')
 ns=json.loads(pinned(root/'namespace-proof-208.json',p['namespace_proof_sha256'],'watch namespace'));require(ns==p['namespace_proof']['evaluation'] and ns['token']==ns['dmi_uuid']==u and ns['proc_interfaces']==ns['sysfs_interfaces']==['lo'] and all(ns['namespaces'][k]!=p['namespace_proof']['parent'][k] for k in ('mnt','pid','net')),'watch namespace differs');priv=json.loads(pinned(root/'privilege-proof.json',p['privilege_proof_sha256'],'watch privilege'));require(priv==p['privilege_proof'] and priv['vm_uuid']==u and (priv['uid'],priv['euid'],priv['gid'],priv['egid'])==(2000,2000,2000,2000) and priv['groups']==[] and priv['no_new_privs']=='1' and priv['cap_eff']=='0000000000000000','watch privilege differs')
 with tarfile.open(root/'payload.tar') as tar:
  members=tar_members(tar);source=[m.name for m in members if m.isfile() and (m.name.startswith('harness/') and not m.name.startswith('harness/suites/') or m.name=='loadable-parity/runner.py')];require(len(source)==12 and {m.name for m in members}==set(source)|{'candidate','harness/suites/optional-frozen.json'},'watch payload membership differs');require(sha(safe_member(tar,'candidate'))==expected_binary and sha(safe_member(tar,'harness/suites/optional-frozen.json'))==p['frozen_fixture_sha256'],'watch payload candidate or fixture differs')
  for name in source:
   key=('tests/parity-vm/'+name.removeprefix('harness/')) if name.startswith('harness/') else 'tests/'+name
   require(sha(safe_member(tar,name))==inventory[key],'watch source differs: '+name)
  fixture=json.loads(safe_member(tar,'harness/suites/optional-frozen.json'));by={c['id']:c for c in fixture['cases']};require(set(by)=={CASE,CONTROL} and canonical(by[CASE])==CASE_HASH and canonical(by[CONTROL])==CONTROL_HASH,'watch frozen cases differ');case=by[CASE]
  for c in by.values():
   for helper,digest in c['helpers_sha256'].items():require(sha(safe_member(tar,'harness/'+helper))==digest,'watch helper differs')
 s=json.loads(pinned(root/'guest-summary.json',p['guest_summary_sha256'],'watch summary'));rows=s['cases'];by={x['id']:x for x in rows};checks={'selfcheck-'+x for x in CHECKS};require(s['vm_uuid']==u and s['binary_sha256']==expected_binary and s['selected_case_ids']==[CONTROL,CASE] and len(rows)==15 and set(by)==checks|{CONTROL,CASE} and all(by[x]['status']=='PASS' for x in checks) and by[CONTROL]['status']=='PASS' and by[CASE]['status']=='FAIL' and not by[CASE]['reference_problems'] and not by[CASE]['harness_errors'],'watch summary differs')
 with tarfile.open(root/'evidence.tar') as tar:
  tar_members(tar);raw={}
  for label,cid,side in [('control',CONTROL,'candidate'),('candidate',CASE,'candidate'),('reference',CASE,'reference')]:
   b=safe_member(tar,'results/'+cid+'/'+side+'.json');require(sha(b)==a['raw_sha256'][label],'watch raw side differs');raw[label]=json.loads(b)
  for v in raw.values():
   require(v['setup']['status']==0 and v['harness_error'] is None and v['decoder_error'] is None and v['terminal_restored'] and not v['stray_processes'],'watch PTY control differs');e=v['events'][1];require(e['action']=='resize' and e['before_size'][:2]==[24,80] and e['after_size'][:2]==[24,40] and e['foreground_group']==e['leader_pid']==v['terminal181_leader_birth'][1],'watch resize attribution differs')
  candidate=raw['candidate'];reference=raw['reference'];control=raw['control'];require(control['status']==0 and any('WINCH-SAW-24x40' in x for x in control['rendered_screen']) and reference['status']==0 and reference['error'] is None and reference['rendered_screen'][1]=='0123456789ENDMARK' and candidate['status']==137 and candidate['signal']==9 and candidate['rendered_screen'][1]=='' and 'wall-clock limit waiting for step 2 screen' in candidate['error'] and [x['step'] for x in candidate['events']]==[0,1] and len(base64.b64decode(candidate['screen_base64']))==candidate['events'][1]['offset']==candidate['terminal181_output_chunks'][-1]['end'] and 5_000_000_000<candidate['terminal213_failure_ns']-candidate['events'][1]['monotonic_ns']<10_000_000_000 and candidate['terminal213_failure_ns']-candidate['events'][1]['monotonic_ns']==a['resize_to_failure_ns'] and [x['step'] for x in reference['events']]==[0,1,2,3,3],'watch reached observation differs')
 comp=p['compatibility'];handoff=json.loads(pinned(root/'compat/handoff.json',comp['handoff_sha256'],'watch handoff'));require(handoff==comp['handoff'] and handoff['vm_uuid']==u and handoff['status']=='PASS' and handoff['candidate_sha256']==expected_binary and handoff['selected_ids']==[CONTROL,CASE],'watch compatibility differs');ev=unit_proof(root/'run.log.unit-proof.json',p['guest_unit_proofs']['run.log.unit-proof.json'],u,'bashos-evaluation-'+u[:8]+'.service',1);sv=unit_proof(root/'compat/run.log.unit-proof.json',p['compatibility_unit_proofs']['run.log.unit-proof.json'],u,'bashos-optional-'+u[:8]+'-reference.service',0);require(a['units']=={'evaluator':ev,'compatibility':sv},'watch unit receipt differs');t=json.loads((root/'vm/teardown.json').read_bytes());require(t==p['teardown'] and t['vm_uuid']==u and t['clean_poweroff'] and not t['forced_stop'] and t['qemu_exit_status']==0 and t['poweroff_request']==0 and t['scope_quiescent'] and t['proof_durable'] and t['cgroup_events']['removed'],'watch teardown differs')
 return ([{'record':by[CASE],'definition':case,'sources':{},'run':spec['name']}],{'name':spec['name'],'groups':['terminal'],'selected_records':1,'evidence_format':FORMAT,'primary_receipt_sha256':PRIMARY_RECEIPT_SHA256,'candidate_sha256':expected_binary,'vm_uuid':u,'requirement':'watch/watch-terminal-parity/r6','provenance_sha256':a['provenance_sha256'],'evidence_sha256':a['evidence_sha256'],'units':{'evaluator':ev,'compatibility':sv},'teardown':t,'overlay_discarded':True})
